let mongoose;
try {
  mongoose = require("mongoose");
} catch (err) {
  console.warn("Mongoose loading notice:", err.message);
}

let isConnected = false;

const connectDB = function () {
  const mongoURI = process.env.MONGO_URI || "mongodb://127.0.0.1:27017/gemini_api";

  if (!mongoose) {
    console.log("Database Driver Notice: Running in standalone memory mode.");
    return Promise.resolve(false);
  }

  console.log("Connecting to MongoDB at:", mongoURI);

  return mongoose
    .connect(mongoURI)
    .then(function () {
      isConnected = true;
      console.log("MongoDB Connected Successfully");
    })
    .catch(function (error) {
      isConnected = false;
      console.warn("MongoDB Connection Notice:", error.message || error);
      console.warn("API running in standalone mode without active database connection.");
    });
};

connectDB.getStatus = function () {
  return isConnected;
};

module.exports = connectDB;

const express = require("express");
const router = express.Router();
const connectDB = require("../config/db");

// In-memory data store for fallback
let items = [
  { id: "1", name: "Sample Item 1", description: "Demo item for testing backend API", createdAt: new Date().toISOString() },
  { id: "2", name: "Sample Item 2", description: "Another demo item", createdAt: new Date().toISOString() }
];

// Health Check Endpoint
router.get("/health", function (req, res) {
  res.json({
    success: true,
    message: "API backend is running successfully",
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// System Status Endpoint
router.get("/status", function (req, res) {
  const dbStatus = connectDB.getStatus ? connectDB.getStatus() : false;
  res.json({
    success: true,
    server: "Node.js Express Backend",
    port: process.env.PORT || 5000,
    databaseConnected: dbStatus,
    mode: dbStatus ? "MongoDB Connected" : "Standalone Memory Mode",
    timestamp: new Date().toISOString()
  });
});

// GET all items
router.get("/items", function (req, res) {
  res.json({
    success: true,
    count: items.length,
    data: items
  });
});

// GET single item
router.get("/items/:id", function (req, res) {
  const item = items.find(function (i) { return i.id === req.params.id; });
  if (!item) {
    return res.status(404).json({ success: false, message: "Item not found" });
  }
  res.json({ success: true, data: item });
});

// POST create item
router.post("/items", function (req, res) {
  const name = req.body && req.body.name ? req.body.name : ("Item " + (items.length + 1));
  const description = req.body && req.body.description ? req.body.description : "No description provided";

  const newItem = {
    id: String(Date.now()),
    name: name,
    description: description,
    createdAt: new Date().toISOString()
  };

  items.push(newItem);
  res.status(201).json({
    success: true,
    message: "Item created successfully",
    data: newItem
  });
});

// DELETE item
router.delete("/items/:id", function (req, res) {
  const initialLength = items.length;
  items = items.filter(function (i) { return i.id !== req.params.id; });

  if (items.length === initialLength) {
    return res.status(404).json({ success: false, message: "Item not found" });
  }

  res.json({ success: true, message: "Item deleted successfully" });
});

module.exports = router;

const express = require("express");
const cors = require("cors");
const dotenv = require("dotenv");

const connectDB = require("./config/db");
const apiRoutes = require("./routes/apiRoutes");

dotenv.config();

const app = express();

// Middleware
app.use(cors());
app.use(express.json());

// Database Connection
connectDB();

// Register API Routes
app.use("/api", apiRoutes);

// Root Route
app.get("/", function (req, res) {
  res.json({
    success: true,
    message: "Welcome to Gemini API Server",
    endpoints: {
      health: "/api/health",
      status: "/api/status",
      items: "/api/items"
    }
  });
});

// 404 Route Handler
app.use(function (req, res) {
  res.status(404).json({
    success: false,
    message: "Endpoint not found: " + req.originalUrl
  });
});

// Start Server
const PORT = process.env.PORT || 5000;

const server = app.listen(PORT, function () {
  console.log("==========================================");
  console.log("  Gemini API Backend Running Successfully ");
  console.log("  URL: http://localhost:" + PORT);
  console.log("  Health Check: http://localhost:" + PORT + "/api/health");
  console.log("  Status Check: http://localhost:" + PORT + "/api/status");
  console.log("==========================================");
});

module.exports = app;

