const http = require("http");
const url = require("url");
const dotenv = require("dotenv");

const connectDB = require("./config/db");

dotenv.config();

// Connect Database (or run in standalone mode)
connectDB();

// In-memory data store for API items
let items = [
  { id: "1", name: "Sample Item 1", description: "Demo item for testing backend API", createdAt: new Date().toISOString() },
  { id: "2", name: "Sample Item 2", description: "Another demo item", createdAt: new Date().toISOString() }
];

const server = http.createServer(function (req, res) {
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;
  const method = req.method;

  console.log("[" + new Date().toISOString() + "] " + method + " " + pathname);

  // Enable Full CORS for all clients & browsers
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Requested-With");

  // Handle CORS preflight
  if (method === "OPTIONS") {
    res.statusCode = 200;
    return res.end();
  }

  // JSON response helper
  function sendJson(statusCode, data) {
    res.statusCode = statusCode;
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.end(JSON.stringify(data, null, 2));
  }

  // Health Endpoint
  if (pathname === "/api/health") {
    return sendJson(200, {
      success: true,
      message: "API backend is running successfully",
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  }

  // System Status Endpoint
  if (pathname === "/api/status") {
    const dbStatus = connectDB.getStatus ? connectDB.getStatus() : false;
    return sendJson(200, {
      success: true,
      server: "Node.js Gemini API Server",
      port: process.env.PORT || 5000,
      databaseConnected: dbStatus,
      mode: dbStatus ? "MongoDB Connected" : "Standalone Memory Mode",
      timestamp: new Date().toISOString()
    });
  }

  // Items Endpoints (CRUD)
  if (pathname === "/api/items" && method === "GET") {
    return sendJson(200, {
      success: true,
      count: items.length,
      data: items
    });
  }

  if (pathname.indexOf("/api/items/") === 0 && method === "GET") {
    const id = pathname.replace("/api/items/", "");
    const item = items.find(function (i) { return i.id === id; });
    if (!item) {
      return sendJson(404, { success: false, message: "Item not found" });
    }
    return sendJson(200, { success: true, data: item });
  }

  if (pathname === "/api/items" && method === "POST") {
    let body = "";
    req.on("data", function (chunk) { body += chunk; });
    req.on("end", function () {
      let parsed = {};
      try { parsed = JSON.parse(body); } catch (e) {}
      const newItem = {
        id: String(Date.now()),
        name: parsed.name || ("Item " + (items.length + 1)),
        description: parsed.description || "No description provided",
        createdAt: new Date().toISOString()
      };
      items.push(newItem);
      return sendJson(201, {
        success: true,
        message: "Item created successfully",
        data: newItem
      });
    });
    return;
  }

  if (pathname.indexOf("/api/items/") === 0 && method === "DELETE") {
    const id = pathname.replace("/api/items/", "");
    const initialLen = items.length;
    items = items.filter(function (i) { return i.id !== id; });
    if (items.length === initialLen) {
      return sendJson(404, { success: false, message: "Item not found" });
    }
    return sendJson(200, { success: true, message: "Item deleted successfully" });
  }

  // Root Index
  if (pathname === "/") {
    return sendJson(200, {
      success: true,
      message: "Welcome to Gemini API Server",
      endpoints: {
        health: "http://localhost:" + (process.env.PORT || 5000) + "/api/health",
        status: "http://localhost:" + (process.env.PORT || 5000) + "/api/status",
        items: "http://localhost:" + (process.env.PORT || 5000) + "/api/items"
      }
    });
  }

  // 404 Route
  return sendJson(404, {
    success: false,
    message: "Endpoint not found: " + pathname
  });
});

const PORT = parseInt(process.env.PORT, 10) || 5000;

server.listen(PORT, function () {
  console.log("==========================================");
  console.log("  Gemini API Server Running Successfully  ");
  console.log("  Port: " + PORT);
  console.log("  Health URL: http://localhost:" + PORT + "/api/health");
  console.log("  Status URL: http://localhost:" + PORT + "/api/status");
  console.log("==========================================");
});

module.exports = server;

