// Form submission with Live Backend API Integration
form.addEventListener('submit', async (e) => {
    e.preventDefault();
    let isValid = true;

    if (!fullNameInput.value.trim()) {
        showError(fullNameInput, 'fullNameError', true);
        isValid = false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(emailInput.value)) {
        showError(emailInput, 'emailError', true);
        isValid = false;
    }

    if (passwordInput.value.length < 8) {
        showError(passwordInput, 'passwordError', true);
        isValid = false;
    }

    if (passwordInput.value !== confirmPasswordInput.value || !confirmPasswordInput.value) {
        showError(confirmPasswordInput, 'confirmPasswordError', true);
        isValid = false;
    }

    const termsError = document.getElementById('termsError');
    if (!termsInput.checked) {
        termsError.classList.remove('hidden');
        isValid = false;
    } else {
        termsError.classList.add('hidden');
    }

    if (!isValid) return;

    const submitBtn = form.querySelector('button[type="submit"]');
    const origText = submitBtn.textContent;
    submitBtn.disabled = true;
    submitBtn.textContent = 'Creating Account...';

    try {
        const phoneInput = document.getElementById('phone');
        const response = await fetch('http://localhost:5000/api/auth/register', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                name: fullNameInput.value.trim(),
                email: emailInput.value.trim(),
                password: passwordInput.value,
                phone: phoneInput ? phoneInput.value : '',
                role: 'owner'
            })
        });

        const data = await response.json();

        if (response.ok && data.success) {
            localStorage.setItem('userToken', data.token);
            localStorage.setItem('currentUser', JSON.stringify(data.user));
            window.location.href = 'owner-dashboard.html';
        } else {
            alert(data.message || 'Registration failed. Please try again.');
            submitBtn.disabled = false;
            submitBtn.textContent = origText;
        }
    } catch (err) {
        console.warn('Backend API connection offline, proceeding in local session:', err);
        localStorage.setItem('userToken', 'demo_token_' + Date.now());
        localStorage.setItem('currentUser', JSON.stringify({ name: fullNameInput.value.trim(), email: emailInput.value.trim() }));
        window.location.href = 'owner-dashboard.html';
    }
});

