const mongoose = require("mongoose");

const PetSchema = new mongoose.Schema(
  {
    name: { type: String, required: [true, "Pet name is required"], trim: true },
    type: { type: String, required: [true, "Pet type is required"], default: "Dog" },
    breed: { type: String, default: "Mixed" },
    gender: { type: String, enum: ["Male", "Female"], default: "Male" },
    age: { type: Number, default: 1 },
    ageUnit: { type: String, enum: ["Years", "Months"], default: "Years" },
    color: { type: String, default: "Brown" },
    weight: { type: Number, default: 5 },
    weightUnit: { type: String, enum: ["kg", "lb"], default: "kg" },
    image: { type: String, default: "https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=500&auto=format&fit=crop" },
    description: { type: String, default: "A friendly and healthy pet." },
    vaccinated: { type: Boolean, default: true },
    vaccinationDate: { type: Date, default: Date.now },
    healthStatus: { type: String, enum: ["Healthy", "Sick", "Under Treatment"], default: "Healthy" },
    ownerName: { type: String, default: "Jane Doe" },
    ownerPhone: { type: String, default: "(555) 123-4567" },
    ownerEmail: { type: String, default: "owner@example.com" },
    address: { type: String, default: "123 Pet Street, Animalville" },
    status: { type: String, enum: ["Available", "Adopted", "Sold", "Inactive"], default: "Available" }
  },
  {
    timestamps: true
  }
);

let Pet;
try {
  Pet = mongoose.models.Pet || mongoose.model("Pet", PetSchema);
} catch (e) {
  Pet = null;
}

module.exports = Pet;

const express = require("express");
const router = express.Router();
const Pet = require("../models/Pet");
const connectDB = require("../config/db");

// Initial sample memory store for fallback or initial setup
let memoryPets = [
  {
    _id: "pet_101",
    id: 101,
    name: "Luna",
    type: "Dog",
    breed: "Golden Retriever",
    gender: "Female",
    age: 3,
    ageUnit: "Years",
    color: "Golden",
    weight: 24,
    weightUnit: "kg",
    image: "https://images.unsplash.com/photo-1552053831-71594a27632d?w=600&auto=format&fit=crop",
    description: "Luna is an energetic, gentle Golden Retriever who loves swimming and playing fetch.",
    vaccinated: true,
    vaccinationDate: "2026-01-15",
    healthStatus: "Healthy",
    ownerName: "Sarah Jenkins",
    ownerPhone: "(555) 234-5678",
    ownerEmail: "sarah@example.com",
    address: "742 Evergreen Terrace, Springfield",
    status: "Available",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  },
  {
    _id: "pet_102",
    id: 102,
    name: "Milo",
    type: "Cat",
    breed: "British Shorthair",
    gender: "Male",
    age: 2,
    ageUnit: "Years",
    color: "Silver Grey",
    weight: 4.5,
    weightUnit: "kg",
    image: "https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=600&auto=format&fit=crop",
    description: "Milo is a calm and affectionate cat who enjoys sunbathing and cozy naps.",
    vaccinated: true,
    vaccinationDate: "2025-11-20",
    healthStatus: "Healthy",
    ownerName: "Alex Rivera",
    ownerPhone: "(555) 876-5432",
    ownerEmail: "alex@example.com",
    address: "108 Ocean Drive, Miami",
    status: "Available",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  },
  {
    _id: "pet_103",
    id: 103,
    name: "Coco",
    type: "Bird",
    breed: "Macaw Parrot",
    gender: "Male",
    age: 18,
    ageUnit: "Months",
    color: "Blue & Gold",
    weight: 1.2,
    weightUnit: "kg",
    image: "https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=600&auto=format&fit=crop",
    description: "Coco is a talkative macaw parrot who loves whistling tunes and eating fresh fruits.",
    vaccinated: true,
    vaccinationDate: "2026-03-01",
    healthStatus: "Healthy",
    ownerName: "David Miller",
    ownerPhone: "(555) 432-1098",
    ownerEmail: "david@example.com",
    address: "45 Pine Forest Road, Austin",
    status: "Available",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

function isDbAvailable() {
  return connectDB.getStatus ? connectDB.getStatus() : false;
}

// Seed initial memory pets into DB if DB connected and empty
async function seedPetsIfEmpty() {
  if (isDbAvailable() && Pet) {
    try {
      const count = await Pet.countDocuments();
      if (count === 0) {
        await Pet.insertMany(memoryPets.map(function(p) {
          const pCopy = Object.assign({}, p);
          delete pCopy._id;
          return pCopy;
        }));
        console.log("Seeded initial pets into MongoDB");
      }
    } catch (e) {
      console.warn("Pet seeding notice:", e.message);
    }
  }
}

// GET /api/pets - List all pets
router.get("/", async function (req, res) {
  try {
    if (isDbAvailable() && Pet) {
      await seedPetsIfEmpty();
      const query = {};
      if (req.query.type) query.type = req.query.type;
      if (req.query.status) query.status = req.query.status;
      if (req.query.healthStatus) query.healthStatus = req.query.healthStatus;

      const dbPets = await Pet.find(query).sort({ createdAt: -1 });
      return res.json({
        success: true,
        count: dbPets.length,
        source: "MongoDB",
        data: dbPets
      });
    }

    // Memory Fallback
    let filteredPets = memoryPets;
    if (req.query.type) {
      filteredPets = filteredPets.filter(function (p) { return p.type.toLowerCase() === req.query.type.toLowerCase(); });
    }
    if (req.query.status) {
      filteredPets = filteredPets.filter(function (p) { return p.status.toLowerCase() === req.query.status.toLowerCase(); });
    }

    return res.json({
      success: true,
      count: filteredPets.length,
      source: "Memory",
      data: filteredPets
    });
  } catch (error) {
    console.error("GET /api/pets Error:", error);
    return res.status(500).json({ success: false, message: error.message });
  }
});

// GET /api/pets/:id - Get single pet
router.get("/:id", async function (req, res) {
  try {
    const idParam = req.params.id;

    if (isDbAvailable() && Pet) {
      const dbPet = await Pet.findById(idParam).catch(function () { return null; });
      if (dbPet) return res.json({ success: true, data: dbPet });
    }

    const memPet = memoryPets.find(function (p) {
      return String(p._id) === String(idParam) || String(p.id) === String(idParam);
    });

    if (!memPet) {
      return res.status(404).json({ success: false, message: "Pet not found" });
    }

    return res.json({ success: true, data: memPet });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

// POST /api/pets - Create new pet with all 22 fields
router.post("/", async function (req, res) {
  try {
    const body = req.body || {};

    if (!body.name) {
      return res.status(400).json({ success: false, message: "Pet name is required." });
    }

    const petData = {
      name: body.name,
      type: body.type || "Dog",
      breed: body.breed || "Mixed Breed",
      gender: body.gender || "Male",
      age: Number(body.age) || 1,
      ageUnit: body.ageUnit || "Years",
      color: body.color || "Brown",
      weight: Number(body.weight) || 5,
      weightUnit: body.weightUnit || "kg",
      image: body.image || "https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=500&auto=format&fit=crop",
      description: body.description || "A lovely pet looking for care.",
      vaccinated: body.vaccinated === undefined ? true : Boolean(body.vaccinated),
      vaccinationDate: body.vaccinationDate || new Date().toISOString().split("T")[0],
      healthStatus: body.healthStatus || "Healthy",
      ownerName: body.ownerName || "Pet Owner",
      ownerPhone: body.ownerPhone || "(555) 000-0000",
      ownerEmail: body.ownerEmail || "owner@example.com",
      address: body.address || "Main Street",
      status: body.status || "Available",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    // 1. Save to MongoDB if available
    if (isDbAvailable() && Pet) {
      const createdDbPet = await Pet.create(petData);
      return res.status(201).json({
        success: true,
        message: "Pet created successfully in MongoDB!",
        data: createdDbPet
      });
    }

    // 2. Save to Memory Store
    petData._id = "pet_" + Date.now();
    petData.id = Date.now();
    memoryPets.unshift(petData);

    return res.status(201).json({
      success: true,
      message: "Pet created successfully! (Memory Mode)",
      data: petData
    });
  } catch (error) {
    console.error("POST /api/pets Error:", error);
    return res.status(500).json({ success: false, message: error.message });
  }
});

// PUT /api/pets/:id - Update existing pet
router.put("/:id", async function (req, res) {
  try {
    const idParam = req.params.id;
    const body = req.body || {};
    body.updatedAt = new Date().toISOString();

    if (isDbAvailable() && Pet) {
      const updatedDbPet = await Pet.findByIdAndUpdate(idParam, body, { new: true });
      if (updatedDbPet) {
        return res.json({ success: true, message: "Pet updated successfully", data: updatedDbPet });
      }
    }

    const index = memoryPets.findIndex(function (p) {
      return String(p._id) === String(idParam) || String(p.id) === String(idParam);
    });

    if (index === -1) {
      return res.status(404).json({ success: false, message: "Pet not found" });
    }

    memoryPets[index] = Object.assign({}, memoryPets[index], body, { updatedAt: new Date().toISOString() });

    return res.json({
      success: true,
      message: "Pet updated successfully",
      data: memoryPets[index]
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

// DELETE /api/pets/:id - Delete pet
router.delete("/:id", async function (req, res) {
  try {
    const idParam = req.params.id;

    if (isDbAvailable() && Pet) {
      const deletedDbPet = await Pet.findByIdAndDelete(idParam);
      if (deletedDbPet) {
        return res.json({ success: true, message: "Pet deleted successfully" });
      }
    }

    const initialLen = memoryPets.length;
    memoryPets = memoryPets.filter(function (p) {
      return String(p._id) !== String(idParam) && String(p.id) !== String(idParam);
    });

    if (memoryPets.length === initialLen) {
      return res.status(404).json({ success: false, message: "Pet not found" });
    }

    return res.json({ success: true, message: "Pet deleted successfully" });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

module.exports = router;

const express = require("express");
const cors = require("cors");
const dotenv = require("dotenv");

const connectDB = require("./config/db");
const apiRoutes = require("./routes/apiRoutes");
const authRoutes = require("./routes/authRoutes");
const petRoutes = require("./routes/petRoutes");

dotenv.config();

const app = express();

// Middleware
app.use(cors());
app.use(express.json({ limit: "10mb" }));
app.use(express.urlencoded({ extended: true, limit: "10mb" }));

// Request logging middleware
app.use(function (req, res, next) {
  console.log("[" + new Date().toISOString() + "] " + req.method + " " + req.url);
  next();
});

// Database Connection
connectDB();

// Register API Routes
app.use("/api/auth", authRoutes);
app.use("/api/pets", petRoutes);
app.use("/api", apiRoutes);

// Root Index Route
app.get("/", function (req, res) {
  res.json({
    success: true,
    message: "Welcome to Gemini Backend API Server",
    endpoints: {
      health: "/api/health",
      status: "/api/status",
      login: "/api/auth/login",
      register: "/api/auth/register",
      pets: "/api/pets",
      items: "/api/items"
    }
  });
});

// 404 Route Handler
app.use(function (req, res) {
  res.status(404).json({
    success: false,
    message: "Endpoint not found: " + req.originalUrl
  });
});

// Start Server
const PORT = process.env.PORT || 5000;

app.listen(PORT, function () {
  console.log("==========================================");
